export const GOVERNED_OPERATIONS=Object.freeze(['display','cache','history','derivative','paidAnalysis','export','apiResale','aiUse']);const OPS=new Set(GOVERNED_OPERATIONS);
export function evaluateSourceOperation(source,operation,{derivedOnly=false}={}){if(!source?.sourceRef)throw new TypeError('sourceRef is required');if(!OPS.has(operation))throw new TypeError(`unknown operation: ${operation}`);if(source.status==='BLOCKED_RIGHTS')return Object.freeze({state:'BLOCKED',reason:'SOURCE_BLOCKED_RIGHTS'});const rights=source.rights??{};if(rights[operation]!==true)return Object.freeze({state:'BLOCKED',reason:`RIGHT_${operation.toUpperCase()}_NOT_GRANTED`});if(derivedOnly&&rights.derivative!==true)return Object.freeze({state:'BLOCKED',reason:'DERIVATIVE_NOT_GRANTED'});if(operation==='paidAnalysis'&&rights.derivative!==true&&source.redisplayPolicy!=='ALLOWED')return Object.freeze({state:'BLOCKED',reason:'PAID_DERIVATION_REQUIRES_DERIVATIVE_RIGHT'});return Object.freeze({state:'ALLOWED',sourceRef:source.sourceRef,operation,attributionRequired:source.attributionRequired!==false})}
export function compileSourceGovernance(sources,operations){const rows=[];for(const s of sources??[])for(const op of operations??[])rows.push({sourceRef:s.sourceRef,operation:op,...evaluateSourceOperation(s,op)});const blocked=rows.filter(r=>r.state!=='ALLOWED');return Object.freeze({state:blocked.length?'BLOCKED_PARTIAL':'ALLOWED',rows,blocked})}
